values.content:
Generate a LinkedIn post about: {{ $json.topic }}

Requirements:
- Professional tone
- Include relevant hashtags
- 150-300 words
- Include a call-to-action
- Target audience: {{ $json.target_audience || 'professionals' }}
- Industry focus: {{ $json.industry || 'general business' }}

parameters.jsCode:
// Process and format the generated content
const inputData = $input.first().json;
const linkedinData = $input.all()[1]?.json;
const twitterData = $input.all()[2]?.json;
const blogData = $input.all()[3]?.json;

// Extract content from AI responses
const linkedinPost = linkedinData?.choices?.[0]?.message?.content || linkedinData?.text || 'LinkedIn content generation failed';
const twitterPost = twitterData?.choices?.[0]?.message?.content || twitterData?.text || 'Twitter content generation failed';
const blogArticle = blogData?.choices?.[0]?.message?.content || blogData?.text || 'Blog article generation failed';

// Create structured output
const result = {
  metadata: {
    topic: inputData.topic,
    target_audience: inputData.target_audience || 'general',
    industry: inputData.industry || 'general business',
    generated_at: new Date().toISOString(),
    workflow_version: '1.0'
  },
  content: {
    linkedin: {
      post: linkedinPost,
      platform: 'LinkedIn',
      character_count: linkedinPost.length,
      recommended_posting_time: 'Tuesday-Thursday 8-10 AM or 12-2 PM'
    },
    twitter: {
      post: twitterPost,
      platform: 'Twitter/X',
      character_count: twitterPost.length,
      character_limit_check: twitterPost.length <= 280 ? 'PASS' : 'EXCEEDED',
      recommended_posting_time: 'Monday-Friday 12-3 PM or 5-6 PM'
    },
    blog: {
      article: blogArticle,
      platform: 'Blog/Website',
      word_count: blogArticle.split(' ').length,
      estimated_reading_time: Math.ceil(blogArticle.split(' ').length / 200) + ' minutes'
    }
  },
  publishing_suggestions: {
    content_calendar: {
      week_1: 'Publish blog article',
      week_1_day_2: 'Share LinkedIn post',
      week_1_day_3: 'Post Twitter content',
      week_2: 'Create follow-up Twitter thread',
      week_3: 'Share blog highlights on LinkedIn'
    },
    cross_promotion: {
      linkedin_to_blog: 'Share blog link in LinkedIn post comments',
      twitter_thread: 'Create Twitter thread with blog key points',
      email_newsletter: 'Include blog summary in newsletter'
    }
  }
};

return result;

